CREATE OR REPLACE FUNCTION public.fn_get_latest_child_journey_insight(p_tenant_id uuid, p_child_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, classroom_id uuid, child_id uuid, requested_by_user_id uuid, period_type character varying, period_start_date date, period_end_date date, focus_area character varying, teacher_question text, evidence_count integer, overall_summary text, evidence_gaps text, created_at timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          id, tenant_id, organization_id, classroom_id, child_id,         requested_by_user_id, period_type, period_start_date, period_end_date,         focus_area, teacher_question, evidence_count, overall_summary,         evidence_gaps, created_at     FROM child_journey_insight_requests     WHERE tenant_id = p_tenant_id AND child_id = p_child_id     ORDER BY created_at DESC     LIMIT 1; $function$ ;
